CREATE POLICY subscriber_meeting_request_scope ON public.meeting_requests AS RESTRICTIVE FOR SELECT TO authenticated USING (public.subscriber_can_see(auth.uid(),requester_id) AND public.subscriber_can_see(auth.uid(),recipient_id));
CREATE POLICY meetings_plan_access ON public.meetings AS RESTRICTIVE FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'facilitador') OR public.has_module_access(auth.uid(),'can_access_meetings')) WITH CHECK (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'facilitador'));
CREATE OR REPLACE FUNCTION public.admin_change_community_role(_profile_id uuid,_role app_role,_team_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') OR NOT public.is_active_user(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; PERFORM 1 FROM public.profiles WHERE id=_profile_id AND is_active FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Pessoa inativa ou inexistente'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_profile_id AND role IN ('admin','facilitador')) THEN RAISE EXCEPTION 'Papel administrativo exige fluxo específico'; END IF; IF _role NOT IN ('convidado','assinante','membro') THEN RAISE EXCEPTION 'Papel inválido'; END IF; IF _role='assinante' AND NOT EXISTS(SELECT 1 FROM public.billing_subscriptions s JOIN public.billing_plans p ON p.id=s.plan_id WHERE s.profile_id=_profile_id AND s.status='active' AND p.active AND p.audience='assinante') THEN RAISE EXCEPTION 'Atribua um plano Assinante ativo antes'; END IF; IF _role='convidado' AND EXISTS(SELECT 1 FROM public.billing_subscriptions WHERE profile_id=_profile_id AND status IN ('active','draft','past_due')) THEN RAISE EXCEPTION 'Revise ou cancele a assinatura antes de retornar a Convidado'; END IF; IF _role='membro' AND (_team_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.teams WHERE id=_team_id)) THEN RAISE EXCEPTION 'Selecione o Grupo'; END IF; IF _role='membro' AND EXISTS(SELECT 1 FROM public.billing_subscriptions s JOIN public.billing_plans p ON p.id=s.plan_id WHERE s.profile_id=_profile_id AND s.status IN ('active','draft','past_due') AND p.audience='assinante') THEN RAISE EXCEPTION 'Revise o plano Assinante antes de promover a Membro'; END IF; DELETE FROM public.team_members WHERE user_id=_profile_id; DELETE FROM public.user_roles WHERE user_id=_profile_id; INSERT INTO public.user_roles(user_id,role) VALUES(_profile_id,_role); IF _role='membro' THEN INSERT INTO public.team_members(user_id,team_id,is_facilitator) VALUES(_profile_id,_team_id,false); END IF; INSERT INTO public.activity_feed(user_id,activity_type,title,metadata) VALUES(_profile_id,'role_changed','Seu papel foi atualizado',jsonb_build_object('role',_role,'admin_id',auth.uid())); END $$;
REVOKE ALL ON FUNCTION public.admin_change_community_role(uuid,app_role,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_change_community_role(uuid,app_role,uuid) TO authenticated;
COMMENT ON FUNCTION public.admin_change_community_role(uuid,app_role,uuid) IS 'Explicit admin-only role transition, locked active profile, administrative targets protected, open subscriptions preserved or require review, no new attendance or points.';
DO $$ DECLARE def text; BEGIN def:=pg_get_functiondef('public.respond_premium_invitation(uuid,boolean)'::regprocedure); def:=replace(def,'AND status IN (''invited'',''confirmed'')','AND status IN (''invited'',''confirmed'') AND EXISTS(SELECT 1 FROM public.meetings m WHERE m.id=guest_participations.meeting_id AND m.meeting_date >= (now() AT TIME ZONE ''America/Sao_Paulo'')::date)'); EXECUTE def; END $$;